def build_sets():
    sets = []
    for i, (title, points, own_title, own_detail) in enumerate(DEVELOPMENT):
        social = [SOCIAL[(2*i) % len(SOCIAL)], SOCIAL[(2*i+1) % len(SOCIAL)]]
        name, situation, options, choice, advantage, drawbacks = SOLUTIONS[i % len(SOLUTIONS)]
        first = dict(part=1, title='Social Interaction', preparation_seconds=0, speaking_seconds=180,
            topics=[dict(title=t, questions=[q for q,a in qa]) for t,qa in social],
            sample_segments=[dict(label=t+' · '+q, text=a) for t,qa in social for q,a in qa])
        second_sample = (
            'In this situation, I would choose '+options[choice].lower()+'. I would base my decision on practicality, '
            'the people involved and the likely experience. The most important reason is that '+advantage+'. '
            'This directly addresses what we need, rather than simply being the most unusual option. '
            'Before making a final arrangement, I would check the cost and availability and discuss the plan with everyone involved. '
            'I have also considered the alternatives. One point is that '+drawbacks[0]+'. Similarly, '+drawbacks[1]+'. '
            'These alternatives are not necessarily bad; they would suit different circumstances. However, their disadvantages '
            'matter more in the situation described. If our budget, schedule or needs changed, I would be willing to reconsider. '
            'For now, '+options[choice].lower()+' offers the best overall balance. I would confirm the practical details, '
            'make a simple plan and keep a backup option in case something unexpected happened.')
        second = dict(part=2, title='Solution Discussion', topic=name, situation=situation, options=options,
            preparation_seconds=60, speaking_seconds=180,
            sample_segments=[dict(label='Choose, justify and compare',text=second_sample)])
        third_sample = ('I would like to discuss '+title.lower()+'. I think this topic matters because it affects '
            'how people organise their lives and make decisions. There are several points to consider. '
            + ' '.join(prefix+', '+heading.lower()+'. '+detail+' This is worth considering when we look at everyday situations.'
                for prefix,(heading,detail) in zip(['First','Second','Third'],points))
            + ' I would also add '+own_title.lower()+'. '+own_detail
            + ' For example, a student or worker could review their own routine and identify one realistic change related to these ideas. '
            'The best choice would depend on their needs and circumstances, so one solution may not suit everyone. '
            'In conclusion, these points show why the topic deserves careful thought. A balanced approach combines practical action '
            'with awareness of possible difficulties. Instead of making a very ambitious promise, I would start with a manageable '
            'step, ask for feedback and review whether it was actually useful.')
        third = dict(part=3,title='Topic Development',topic=title,points=[p[0] for p in points],
            preparation_seconds=60,speaking_seconds=240,
            sample_segments=[dict(label='Develop the topic and add your own idea',text=third_sample)])
        for part in (first,second,third):
            part['reference_answer'] = '\n\n'.join(s['text'] for s in part['sample_segments'])
            part['source'] = 'authored_practice'
        sets.append(dict(id='vstep-'+str(i+1).zfill(2),title=('Morning Routines · Movie · Workplace Stress' if i==0 else title),
                         parts=[first,second,third]))
    return sets


PRACTICE_SETS = build_sets()


def question_text(part):
    if part['part'] == 1:
        return '\n\n'.join(t['title']+'\n'+'\n'.join(t['questions']) for t in part['topics'])
    if part['part'] == 2:
        return part['situation']+'\n'+'\n'.join(str(i+1)+'. '+s for i,s in enumerate(part['options']))
    return part['topic']+'\n'+'\n'.join(part['points']+['Your own idea'])
